public class DefaultPermissionProbe {
 public static String observe() {
  Map<String,Object> row=new Map<String,Object>();
  Schema.DescribeSObjectResult obj=AccessSlip__c.SObjectType.getDescribe();
  Schema.DescribeFieldResult field=AccessSlip__c.Detail__c.getDescribe();
  row.put('crud',new List<Boolean>{obj.isAccessible(),obj.isCreateable(),obj.isUpdateable(),obj.isDeletable()});
  row.put('fls',new List<Boolean>{field.isAccessible(),field.isCreateable(),field.isUpdateable()});
  row.put('name',new List<Boolean>{AccessSlip__c.Name.getDescribe().isAccessible(),AccessSlip__c.Name.getDescribe().isCreateable(),AccessSlip__c.Name.getDescribe().isUpdateable()});
  try { row.put('plainCount',String.valueOf(Database.countQuery('SELECT COUNT() FROM AccessSlip__c'))); } catch(Exception e) {row.put('plainCount',e.getTypeName());}
  try { row.put('systemCount',String.valueOf(Database.countQuery('SELECT COUNT() FROM AccessSlip__c WITH SYSTEM_MODE'))); } catch(Exception e) {row.put('systemCount',e.getTypeName());}
  try { Database.query('SELECT Id,Detail__c FROM AccessSlip__c WITH USER_MODE');row.put('userQuery','ok'); } catch(Exception e) {row.put('userQuery',e.getTypeName());}
  try { List<AccessSlip__c> rows=[SELECT Id,Detail__c FROM AccessSlip__c WITH USER_MODE];row.put('inlineUserQuery','ok'); } catch(Exception e) {row.put('inlineUserQuery',e.getTypeName());}
  try { Database.query('SELECT Id,Detail__c FROM AccessSlip__c WITH SECURITY_ENFORCED');row.put('enforcedQuery','ok'); } catch(Exception e) {row.put('enforcedQuery',e.getTypeName());}
  try { insert new AccessSlip__c(Name='Plain');row.put('plainInsert','ok'); } catch(Exception e) {row.put('plainInsert',e.getTypeName());}
  try { Database.insert(new AccessSlip__c(Name='User'),AccessLevel.USER_MODE);row.put('userInsert','ok'); } catch(Exception e) {row.put('userInsert',e.getTypeName());}
  try { Database.insert(new AccessSlip__c(Name='System'),AccessLevel.SYSTEM_MODE);row.put('systemInsert','ok'); } catch(Exception e) {row.put('systemInsert',e.getTypeName());}
  try { Database.insert(new AccessSlip__c(Name='User field',Detail__c='detail'),AccessLevel.USER_MODE);row.put('userFieldInsert','ok'); } catch(Exception e) {row.put('userFieldInsert',e.getTypeName());}
  try { insert as user new AccessSlip__c(Name='Inline user field',Detail__c='detail');row.put('inlineUserFieldInsert','ok'); } catch(Exception e) {row.put('inlineUserFieldInsert',e.getTypeName());}
  AccessSlip__c writable=new AccessSlip__c(Name='System field',Detail__c='detail');
  Database.insert(writable,AccessLevel.SYSTEM_MODE);
  try { Database.update(new AccessSlip__c(Id=writable.Id,Detail__c='updated'),AccessLevel.USER_MODE);row.put('userFieldUpdate','ok'); } catch(Exception e) {row.put('userFieldUpdate',e.getTypeName());}
  try { update as user new AccessSlip__c(Id=writable.Id,Detail__c='updated');row.put('inlineUserFieldUpdate','ok'); } catch(Exception e) {row.put('inlineUserFieldUpdate',e.getTypeName());}
  for(System.AccessType mode:new List<System.AccessType>{System.AccessType.READABLE,System.AccessType.CREATABLE,System.AccessType.UPDATABLE}) {
   try {
    AccessSlip__c original=new AccessSlip__c(Name='Strip',Detail__c='detail');
    SObjectAccessDecision decision=Security.stripInaccessible(mode,new List<SObject>{original},false);
    Set<String> removed=decision.getRemovedFields().get('AccessSlip__c');
    AccessSlip__c result=(AccessSlip__c)decision.getRecords()[0];
    row.put(String.valueOf(mode),new List<Boolean>{removed!=null&&removed.contains('Name'),removed!=null&&removed.contains('Detail__c'),result.Name==null,result.Detail__c==null,original.Name=='Strip',original.Detail__c=='detail'});
   } catch(Exception e) {row.put(String.valueOf(mode),e.getTypeName());}
  }
  try { Security.stripInaccessible(System.AccessType.READABLE,new List<SObject>{new AccessSlip__c(Name='Enforced')});row.put('rootEnforced','ok'); } catch(Exception e) {row.put('rootEnforced',e.getTypeName());}
  return JSON.serialize(row);
 }
}

